import json
from collections import Counter

def find_separator_unique_value(grid):
    all_values = {}
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            v = grid[r][c]
            if v not in all_values:
                all_values[v] = []
            all_values[v].append((r, c))

    for r in range(1, len(grid) - 1):
        row_val = grid[r][0]
        if all(grid[r][c] == row_val for c in range(len(grid[r]))):
            value_loc = all_values[row_val]
            if all(v[0] == r for v in value_loc):
                return r, row_val
    return None, None

def transform(grid):
    h = len(grid)
    w = len(grid[0])
    sep_row, sep_val = find_separator_unique_value(grid)
    if sep_row is None:
        sep_row = h // 2

    top = [list(grid[r]) for r in range(sep_row)]
    bottom = [list(grid[r]) for r in range(sep_row + 1, h)]

    output = []
    for r in range(len(bottom)):
        out_row = []
        for c in range(len(bottom[r])):
            if top[r][c] != 0 and bottom[r][c] != 0:
                out_row.append(2)
            else:
                out_row.append(0)
        output.append(out_row)

    return output

